window.captureAskVoice=voice=>{const box=voice?.closest('.qa'),input=box?.querySelector('[data-qa-input]'),status=box?.querySelector('[data-qa-status]'),SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!input)return;if(status)status.textContent='Starting voice input…';if(!SpeechRecognition){if(status)status.textContent='Voice input is not available in this browser.';return}if(voice._cyclingRecognition){voice._cyclingRecognition.stop();return}const recognition=new SpeechRecognition(),base=input.value.trim();let captured='';voice._cyclingRecognition=recognition;recognition.continuous=false;recognition.interimResults=true;recognition.lang=document.documentElement.lang||navigator.language||'en-US';const reset=()=>{delete voice._cyclingRecognition;voice.classList.remove('is-listening');voice.textContent='Use voice';voice.setAttribute('aria-pressed','false')};recognition.onstart=()=>{voice.classList.add('is-listening');voice.textContent='Stop listening';voice.setAttribute('aria-pressed','true');if(status)status.textContent='Listening…'};recognition.onresult=event=>{let interim='';for(let i=event.resultIndex;i<event.results.length;i++){const text=event.results[i][0].transcript.trim();if(event.results[i].isFinal)captured=[captured,text].filter(Boolean).join(' ');else interim=[interim,text].filter(Boolean).join(' ')}input.value=[base,captured,interim].filter(Boolean).join(' ');if(status)status.textContent=interim?'Listening…':'Voice captured.'};recognition.onerror=event=>{if(status)status.textContent=event.error==='not-allowed'?'Microphone access was not allowed.':'Voice input was unavailable.'};recognition.onend=()=>{const wasListening=status?.textContent==='Listening…';reset();if(wasListening&&status)status.textContent=captured?'Voice captured.':'No speech detected.'};try{recognition.start()}catch{reset();if(status)status.textContent='Voice input was unavailable.'}};
