const $=(s,e=document)=>e.querySelector(s), $$=(s,e=document)=>[...e.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const CONFIDENCE_COPY={HIGH:'High location confidence',MEDIUM:'Medium location confidence',LOW:'Low location confidence'};
function pinConfidence(point){const value=String(point?.pin_confidence||'MEDIUM').trim().toUpperCase();return Object.hasOwn(CONFIDENCE_COPY,value)?value:'MEDIUM'}
function pinConfidenceLabel(point){return CONFIDENCE_COPY[pinConfidence(point)]}
function pinConfidenceNote(point){return String(point?.pin_disclaimer||'Location confidence describes the mapped place, not whether a service is currently operating.').trim()}
function confidenceBadge(point,{compact=false}={}){const level=pinConfidence(point),label=pinConfidenceLabel(point);return `<span class="confidence-badge confidence-${level.toLowerCase()}" aria-label="${esc(label)}"><span class="confidence-dot" aria-hidden="true"></span><span class="confidence-label">${compact?esc(level[0]+level.slice(1).toLowerCase()):esc(label)}</span></span>`}
function isSafePublicUrl(value){try{const url=new URL(String(value||''));return url.protocol==='https:'||url.protocol==='http:'?url.href:''}catch{return ''}}
function hasMapCoordinates(point){const latitude=Number(point?.latitude),longitude=Number(point?.longitude);return Number.isFinite(latitude)&&Number.isFinite(longitude)&&latitude>=-90&&latitude<=90&&longitude>=-180&&longitude<=180}
function markerStyle(point){return ({HIGH:{color:'#15583c',fillColor:'#2f7557',fillOpacity:.9},MEDIUM:{color:'#8b651e',fillColor:'#d4a34b',fillOpacity:.9},LOW:{color:'#715078',fillColor:'#9b79a2',fillOpacity:.88,dashArray:'3 3'}})[pinConfidence(point)]}
function publicContactActions(actions){const labels={phone:'Call',whatsapp:'WhatsApp',email:'Email',website:'Website',booking:'Booking',instagram:'Instagram',facebook:'Facebook',directions:'Directions',other:'Public link'},allowed=new Set(Object.keys(labels));return (Array.isArray(actions)?actions:[]).map(action=>{const type=String(action?.type||action?.contact_type||'').toLowerCase(),value=String(action?.value||action?.contact_value||'').trim(),provided=String(action?.href||action?.url||'').trim();if(!allowed.has(type))return null;let href='';if(type==='phone'||type==='whatsapp'){const digits=(provided||value).replace(/\D/g,'');if(digits.length<6||digits.length>16)return null;href=type==='phone'?`tel:+${digits}`:`https://wa.me/${digits}`}else if(type==='email'){const address=(provided.replace(/^mailto:/i,'')||value).trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(address))return null;href=`mailto:${address}`}else href=isSafePublicUrl(provided||value);return href?{href,label:labels[type]}:null}).filter(Boolean)}
function contactActionsMarkup(actions,klass='contact-actions'){const safe=publicContactActions(actions);return safe.length?`<div class="${klass}" aria-label="Public contact links">${safe.map(action=>`<a class="tag" href="${esc(action.href)}" target="${action.href.startsWith('http')?'_blank':'_self'}" rel="${action.href.startsWith('http')?'noreferrer':''}">${esc(action.label)}${action.href.startsWith('http')?' ↗':''}</a>`).join('')}</div>`:''}
function publicSources(point){const candidates=[[point?.primary_location_source_name,point?.primary_location_source_url],[point?.secondary_location_source_name,point?.secondary_location_source_url],[point?.evidence?'Public source':null,point?.source_url]],seen=new Set();return candidates.map(([label,url])=>{const href=isSafePublicUrl(url);if(!href||seen.has(href))return null;seen.add(href);return {href,label:String(label||'Public source')}}).filter(Boolean)}
function sourceLinksMarkup(point,klass='source-actions'){const sources=publicSources(point);return sources.length?`<div class="${klass}">${sources.map(source=>`<a class="under" href="${esc(source.href)}" target="_blank" rel="noreferrer">${esc(source.label)} ↗</a>`).join('')}</div>`:''}
async function api(path,opts={}){const r=await fetch(path,opts);let j;try{j=await r.json()}catch{throw new Error(`Bad response (${r.status})`)}if(!r.ok)throw new Error(j.error||`Request failed (${r.status})`);return j}
function cleanupVisuals(){for(const key of ['map','homeMap']){if(APP[key]){try{APP[key].remove()}catch{}APP[key]=null}}APP.mapLayer=null}
function navigate(path){cleanupVisuals();history.pushState({},'',path);render();scrollTo(0,0)}
