function jumpToGuideSection(id){const target=document.getElementById(id);if(!target)return;const topbar=document.querySelector('.topbar'),guideNav=document.querySelector('.guide-nav'),offset=(topbar?.getBoundingClientRect().height||0)+(guideNav?.getBoundingClientRect().height||0)+18,top=window.scrollY+target.getBoundingClientRect().top-offset;window.scrollTo({top,behavior:'smooth'});history.replaceState({},'',sitePath()+location.search+'#'+id)}
