function navActive(){const p=sitePath();$('.nav a').forEach(a=>a.classList.toggle('active',a.dataset.nav==='field-guides'?/^\/(field-guides|routes|countries)(\/|$)/.test(p):p.startsWith('/'+a.dataset.nav)))}
function syncPageMeta(){
  const p=sitePath(),h1=$('#app h1'),firstCopy=$('#app .hero p, #app .pagehero p, #app main p');
  const pageName=(h1?.textContent||'').trim();
  const homeTitle='Cycling Americas — South America Bikepacking & Bicycle Touring Field Guides';
  const title=(p==='/'||p==='')?homeTitle:(pageName?pageName+' | Cycling Americas':'Cycling Americas');
  const fallback='Free South America bikepacking and bicycle touring field guides with routes, camping, bike repair, water, resupply, ferries, borders and rider-reported practical details.';
  const description=((firstCopy?.textContent||'').trim()||fallback).replace(/\s+/g,' ').slice(0,220);
  document.title=title;
  let desc=document.querySelector('meta[name="description"]');if(desc)desc.setAttribute('content',description);
  let canonical=document.querySelector('link[rel="canonical"]');if(canonical)canonical.setAttribute('href',location.origin+p);
  const values={'og:title':title,'og:description':description,'og:url':location.origin+p};
  Object.entries(values).forEach(([key,value])=>{const node=document.querySelector('meta[property="'+key+'"]');if(node)node.setAttribute('content',value)});
}
function searchBox(placeholder='Search a ride, country, town or service…'){return `<div class="searchbox"><input data-search-input aria-label="Site search" placeholder="${esc(placeholder)}"><button class="btn" data-search-go>Search</button><div class="searchresults" data-search-results></div></div>`}
function initSearch(root=document){$$('[data-search-input]',root).forEach(input=>{const box=input.closest('.searchbox'),res=$('[data-search-results]',box),go=$('[data-search-go]',box);let timer;async function run(){const q=input.value.trim();if(!q){res.style.display='none';return}try{const d=await api('/api/search?q='+encodeURIComponent(q));res.innerHTML=d.results.length?d.results.map(x=>`<a class="searchresult" href="${esc(x.path)}" data-link><small>${esc(x.type)}</small><br><b>${esc(x.name)}</b>${x.region?`<br><span class="meta">${esc(x.region)}</span>`:''}</a>`).join(''):`<div class="searchresult"><b>No exact entity found.</b><br><span class="meta">Try Ask for a planning question.</span></div>`;res.style.display='block'}catch{res.innerHTML='<div class="searchresult">Search is temporarily unavailable.</div>';res.style.display='block'}}input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(run,180)});input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();run()}});go?.addEventListener('click',run);document.addEventListener('click',e=>{if(!box.contains(e.target))res.style.display='none'})})}
function photoCredit(p,compact=false){return `<span class="photo-credit${compact?' compact':''}">Photo: <a href="${esc(p.source)}" target="_blank" rel="noreferrer">${esc(p.author)}</a> · <a href="${esc(p.licenseUrl)}" target="_blank" rel="noreferrer">${esc(p.license)}</a></span>`}
function routePhotoFeature(slug){const p=ROUTE_PHOTOS[slug];if(!p)return '';return `<section class="route-photo-feature" data-route-photo><div class="wrap"><figure><img src="${esc(p.src)}" alt="${esc(p.alt)}"><figcaption><span>${esc(p.title)}</span>${photoCredit(p)}</figcaption></figure></div></section>`}
function enhanceRoutePhoto(){const parts=sitePath().split('/').filter(Boolean);if(parts[0]!=='routes'||!parts[1]||$('[data-route-photo]'))return;const hero=$('.pagehero'),html=routePhotoFeature(parts[1]);if(hero&&html)hero.insertAdjacentHTML('afterend',html)}
async function initHomeMap(){
  if(window.__deferHomepageMap)return;
  const el=$('#home-map'),status=$('#home-map-status'),fallback=$('#home-map-fallback');
  if(!el)return;
  try{
    const d=await api('/api/map');
    if(!document.body.contains(el))return;
    const points=(Array.isArray(d.points)?d.points:[]).filter(hasMapCoordinates);
    status.textContent=`${points.length} publication-safe exact locations · use the full map to filter by country, ride, point type and location confidence.`;
    if(!window.L){el.style.display='none';fallback.style.display='block';return}
    APP.homeMap=L.map(el,{scrollWheelZoom:false}).setView([-18,-67],3);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:18}).addTo(APP.homeMap);
    const bounds=[];
    for(const p of points){
      const latitude=Number(p.latitude),longitude=Number(p.longitude),source=isSafePublicUrl(p.source_url);
      bounds.push([latitude,longitude]);
      const popup=`<b>${esc(p.canonical_name)}</b><div>${esc(p.country_name)} · ${esc(p.display_type)}</div><div>${esc(pinConfidenceLabel(p))}</div><p>${esc(p.summary||'Publication-safe cycling location.')}</p>${source?`<a href="${esc(source)}" target="_blank" rel="noreferrer">Public source ↗</a>`:''}`;
      L.circleMarker([latitude,longitude],{radius:6,weight:2,...markerStyle(p)}).bindPopup(popup).addTo(APP.homeMap);
    }
    if(bounds.length)APP.homeMap.fitBounds(bounds,{padding:[24,24],maxZoom:5});
  }catch(e){
    status.textContent='The homepage map is temporarily unavailable.';
    fallback.style.display='block';
    fallback.textContent=e.message;
  }
}
function enhanceHomeMap(){if(sitePath()!=='/'||$('#home-map'))return;const heading=$$('.head h2').find(x=>x.textContent.trim()==='Camping, repair & useful stops'),section=heading?.closest('.section'),hero=$('.hero'),stats=section?$('.stats',section):null;if(!section||!stats)return;stats.insertAdjacentHTML('beforebegin','<p class="meta" id="home-map-status">Loading publication-safe exact locations…</p><div id="home-map" class="map home-map" aria-label="Interactive map of publication-safe Cycling Americas locations"></div><div id="home-map-fallback" class="mapfallback">Use the full map to browse all publication-safe exact locations.</div>');if(hero)hero.insertAdjacentElement('afterend',section);initHomeMap()}
function enhanceDataCredits(){if(sitePath()!=='/data'||$('[data-photo-credits]'))return;const wrap=$('.section .wrap');if(!wrap)return;const photos=Object.values(ROUTE_PHOTOS),items=photos.map(p=>`<div class="photo-credit-row"><span><b>${esc(p.title)}</b><br><span>Photo by <a class="under" href="${esc(p.source)}" target="_blank" rel="noreferrer">${esc(p.author)}</a></span></span><a class="tag" href="${esc(p.licenseUrl)}" target="_blank" rel="noreferrer">${esc(p.license)}</a></div>`).join('');wrap.insertAdjacentHTML('beforeend',`<details class="card photo-credits-card" data-photo-credits><summary>Photography credits <span>${photos.length} images</span></summary><div class="photo-credit-list">${items}</div><p class="meta"><a class="under" href="/photos/credits.json">Download machine-readable credits →</a></p></details>`)}
