async function initFieldIntelligence(){
  const root=document.querySelector('[data-fi-results]'),status=document.querySelector('[data-fi-status]');
  if(!root)return;
  const data=await api('/api/poi-leads?limit=200');
  const all=Array.isArray(data.records)?data.records:[];
  const search=document.querySelector('[data-fi-search]'),country=document.querySelector('[data-fi-country]'),confidence=document.querySelector('[data-fi-confidence]');
  const render=()=>{
    const q=norm(search?.value||''),cc=String(country?.value||'').toUpperCase(),conf=String(confidence?.value||'').toLowerCase();
    const rows=all.filter(r=>{
      if(cc&&String(r.country_code||r.country_name||'').toUpperCase()!==cc&&String(r.country_name||'').toUpperCase()!==cc)return false;
      if(conf&&String(r.confidence||'').toLowerCase()!==conf)return false;
      if(q&&!norm([r.area,r.country_name,r.label,r.summary,r.location_reason].join(' ')).includes(q))return false;
      return true;
    });
    status.textContent=`${rows.length} area record${rows.length===1?'':'s'} shown · ${rows.reduce((n,r)=>n+Number(r.observations||0),0).toLocaleString()} underlying leads.`;
    root.innerHTML=rows.length?rows.map(r=>{
      const signals=[r.contact_available?'contact exists internally':'',r.vcf_available?'contact card exists internally':'',r.map_signal_available?'map/coordinate signal exists':''].filter(Boolean);
      const dates=[r.first_mention,r.last_mention].filter(Boolean).join(' → ');
      return `<article class="card field-intel-card">
        <div class="tagrow"><span class="tag">${esc(r.country_name||r.country_code||'')}</span><span class="tag">${esc(r.confidence||'Unrated')} confidence</span></div>
        <h3>${esc(r.area||r.label)}</h3>
        <p>${esc(r.summary||'')}</p>
        <p class="meta"><b>${Number(r.observations||0).toLocaleString()}</b> underlying lead${Number(r.observations||0)===1?'':'s'}${dates?' · '+esc(dates):''}</p>
        ${signals.length?`<p class="meta">${signals.map(esc).join(' · ')}</p>`:''}
        <details><summary>Why this area was assigned</summary><p class="meta">${esc(r.location_reason||'Thread context')}</p><p class="meta">${esc(r.status_note||'Historical field intelligence; verify current status.')}</p></details>
      </article>`;
    }).join(''):'<div class="empty"><h3>No matching area records</h3><p>Try a broader town, country, or confidence filter.</p></div>';
  };
  [search,country,confidence].forEach(el=>el?.addEventListener(el===search?'input':'change',render));
  render();
}

async function render(){if(!await resolveGuideLocation())return;navActive();const app=$('#app'),p=sitePath();app.innerHTML='<div class="loading wrap">Loading…</div>';try{let html;if(p==='/'||p==='')html=await home();else if(p==='/field-guides'||p==='/field-guides/')html=await fieldGuidesPage();else if(p==='/routes'||p==='/routes/')html=await routesPage();else if(p.startsWith('/routes/'))html=await routeGuidePage(p.split('/').filter(Boolean)[1]);else if(p.startsWith('/segments/'))html=await segmentPage(p.split('/').filter(Boolean)[1]);else if(p==='/countries'||p==='/countries/')html=await countriesPage();else if(p.startsWith('/countries/'))html=await countryPage(p.split('/').filter(Boolean)[1]);else if(p==='/map'||p==='/map/')html=await mapPage();else if(p==='/field-intelligence'||p==='/field-intelligence/')html=await fieldIntelligencePage();else if(p==='/ask'||p==='/ask/')html=await askPage();else if(p==='/data'||p==='/data/')html=await dataPage();else if(p==='/about'||p==='/about/')html=aboutPage();else if(p==='/privacy'||p==='/privacy/')html=privacyPage();else if(p.startsWith('/stops/'))html=await stopPage(p.split('/').filter(Boolean)[1]);else if(p.startsWith('/places/'))html=await placePage(p.split('/').filter(Boolean)[1]);else html=await home();app.innerHTML=html;syncPageMeta();navActive();initSearch(app);initQa(app);if(p==='/')initHome();if(p==='/routes'||p==='/routes/')initRoutes();if(p==='/map'||p==='/map/')await initMap();if(p==='/field-intelligence'||p==='/field-intelligence/')await initFieldIntelligence();if(p==='/field-guides'||p==='/field-guides/')await initFieldGuides()}catch(e){console.error(e);app.innerHTML=`<section class="section"><div class="wrap"><div class="empty"><h2>Could not load this page</h2><p>${esc(e.message)}</p><button class="btn" onclick="location.reload()">Retry</button></div></div></section>`}}
